from pathlib import Path
import json,re
p=Path(__file__).resolve().parent
cases=[]
for name,warmup,launch in [('hot-passive-01','hot','current'),('40c-original-01','40C','original'),('40c-passive-01','40C','current'),('hot-cooled-original-01','hot_then_cooled','original')]:
 v=json.loads((p/name/'window-comparison.json').read_text());r=json.loads((p/name/'result.json').read_text());meta=v['metadata']
 temps=list(map(float,re.search(r'A1=([\d.]+) A2=([\d.]+) A3=([\d.]+) A4=([\d.]+)',meta['first_work_temperature_line']).groups()))
 missing=[f"A{c['asic']}D{d['domain']}" for c in v['whole']['chips'] for d in c['domains'] if d['percent_ideal']<1]
 cases.append(dict(name=name,warmup=warmup,launch=launch,first_work_temperatures=temps,first10s_ghs=v['first10s']['total_ghs'],whole_ghs=v['whole']['total_ghs'],last10s_ghs=v['last10s']['total_ghs'],failed_domains_under_1_percent=missing,early_qualified=v['first10s']['qualify'],late_qualified=v['last10s']['qualify'],peak_temperature_c=max(t['max'] for t in r['post_launch_temperatures'].values()),invalid_thermal_samples=len(r['thermal_invalid']),measurement_note='Final two snapshots/chip excluded near 120.04s counter expiry' if meta['excluded_rows_near_timer_expiry'] else 'Full 120s observation within 180s counter epoch',binary_sha256=json.loads((p/name/'firmware-identity.json').read_text())['sha256']['probe.bin']))
ref=p.parent/'2026-09-06-1103-saved-image-control';r=json.loads((ref/'result.json').read_text());early=json.loads((p/'saved-control-first10s.json').read_text())
cases.insert(0,dict(name='saved-image-control',warmup='hot',launch='original',first_work_temperatures=[56.98,55.5,56.49,56.0],first10s_ghs=early['first10s_ghs'],whole_ghs=r['windows']['whole_hold']['total_ghs'],last10s_ghs=None,failed_domains_under_1_percent=[],early_qualified=True,late_qualified=True,peak_temperature_c=60.12,invalid_thermal_samples=0,measurement_note='Exact saved binary; full 120s observation',binary_sha256='fe782f3d7e70980c91719aeffeabaf8322779cd61155a8667627a5bc00295313'))
result={'cases':cases,'assessment':{'supported':'Cooler thermal conditions through reinitialization, unloaded PLL ramp, and first work trigger the recent five-domain throughput failure. Prior hot warmup alone does not prevent it after cooling.','not_isolated':'Which exact phase is temperature-sensitive (power-on/reset, PLL ramp, or first job); minimum reliable threshold; ASIC electrical mechanism; residual intermittent hot-start failures.','first_work_sequence':'Both sequences succeeded hot and failed cool in this matrix; no sequence interaction required to explain the severe recent regression.','failure_observation':'All cool-start variants failed both initial and final ten-second windows; no sustained recovery over 120s even after subsequent heating near 60C.','limits':'One additional run per new condition; saved original image succeeded twice across days. This is not a reliability estimate or proof of all temperature/sequence interactions being absent.'}}
(p/'matrix.json').write_text(json.dumps(result,indent=2)+'\n')
for c in cases:print(c['name'],round(c['whole_ghs'],2),c['first_work_temperatures'],c['failed_domains_under_1_percent'])
